function maxTripleProduct(nums: number[]): number {
  let best = -Infinity;
  const n = nums.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      for (let k = j + 1; k < n; k++)
        best = Math.max(best, nums[i] * nums[j] * nums[k]);
  return best;
}

